return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : ((n == 0) || (n == 1)) ? 0 : 2);','language'=>'fr_FR','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Sauvegarde vos fichiers et votre base de données WordPress sur votre propre espace de stockage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 ou tout bucket compatible S3 —, les restaure en une seule fois et importe les sauvegardes créées par d’autres extensions de sauvegarde et de migration.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Sauvegardes','Get Pro: schedules, several storages, encryption'=>'Passez à la version Pro : planifications, plusieurs stockages, chiffrement','Working…'=>'Traitement en cours…','Finished'=>'Terminé','Failed'=>'Échec','Cancelled'=>'Annulé','Cancel'=>'Annuler','Restore'=>'Restaurer','Delete'=>'Supprimer','Delete this backup from your storage? This cannot be undone.'=>'Supprimer cette sauvegarde de votre stockage ? Cette action est irréversible.','No backups yet. Press “Back up now” to make the first one.'=>'Aucune sauvegarde pour le moment. Cliquez sur « Sauvegarder maintenant » pour créer la première.','Reading your storage…'=>'Lecture de votre espace de stockage…','a complete backup, as opposed to an incremental oneFull backup'=>'Sauvegarde complète','a backup holding only what changed since an earlier oneIncremental backup'=>'Sauvegarde incrémentielle','Encrypted'=>'Chiffré','From another site'=>'Depuis un autre site','Database'=>'Base de données','Files'=>'Fichiers','Uploading %1$s: %2$s%%'=>'Téléversement de %1$s : %2$s %%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Connectez-vous à Dropbox dans la fenêtre qui s’est ouverte, puis collez le code affiché par Dropbox :','Saved.'=>'Enregistré.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Supprimer cette destination de l’extension ? Les sauvegardes qui y sont stockées ne sont pas supprimées.','Reload the page to see the restored site.'=>'Rechargez la page pour voir le site restauré.','Storage'=>'Stockage','Import & migrate'=>'Importer et migrer','Settings'=>'Réglages','Sections'=>'Sections','Google Drive is connected.'=>'Google Drive est connecté.','Google Drive could not be connected.'=>'Impossible de connecter Google Drive.','Details'=>'Détails','Back up now'=>'Sauvegarder maintenant','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Les sauvegardes vont vers votre propre stockage, pas sur ce serveur. <a href="%s">Connectez d’abord votre stockage</a>.','What to back up'=>'Éléments à sauvegarder','Files and database'=>'Fichiers et base de données','Database only'=>'Base de données uniquement','Files only'=>'Fichiers uniquement','Note (optional)'=>'Note (facultatif)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Chaque partie est téléversée sur votre stockage et supprimée de ce serveur avant que la suivante ne soit créée, de sorte que la sauvegarde ne prend jamais de place sur votre hébergement.','Your backups'=>'Vos sauvegardes','Refresh'=>'Actualiser','Restore this backup'=>'Restaurer cette sauvegarde','Passphrase'=>'Phrase secrète','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Je comprends que cela remplace les fichiers et la base de données de ce site par ceux de la sauvegarde. Les fichiers qui ne figurent pas dans la sauvegarde sont conservés.','Recent activity'=>'Activité récente','Backup'=>'Sauvegarde','Restore / import'=>'Restaurer / importer','Running'=>'En cours d’exécution','Your storage'=>'Votre stockage' . "\0" . 'Vos destinations de stockage' . "\0" . 'Vos destinations de stockage','No storage yet. Choose where your backups go below.'=>'Aucun stockage pour le moment. Choisissez ci-dessous où vont vos sauvegardes.','Ready'=>'Prêt','Not connected'=>'Non connecté','Connect'=>'Connecter','Test'=>'Tester','Edit'=>'Modifier','Remove'=>'Retirer','Add storage'=>'Ajouter du stockage','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Les sauvegardes sont envoyées vers un seul emplacement de stockage. Pour en utiliser un autre, modifiez ou supprimez celui ci-dessus.','Kind of storage'=>'Type de stockage','Name (for you)'=>'Nom (pour vous)','Provider'=>'Fournisseur','Cloudflare account id'=>'ID du compte Cloudflare','Endpoint address'=>'Adresse du point de terminaison','Region'=>'Région','Bucket'=>'Bucket','Access key id'=>'ID de clé d’accès','Secret access key'=>'Clé d’accès secrète','Leave empty to keep the saved key'=>'Laissez vide pour conserver la clé enregistrée','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Pour Cloudflare R2 : dans le tableau de bord Cloudflare, ouvrez R2, créez un compartiment (bucket), puis « Manage R2 API tokens » → créez un jeton avec les autorisations Object Read & Write pour ce compartiment, et copiez l’access key id et le secret ici.','Dropbox app key'=>'Clé d’application Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Créez une application sur dropbox.com/developers/apps (Scoped access, App folder) avec les autorisations files.content.read, files.content.write et files.metadata.read, puis copiez sa App key ici. Enregistrez, puis appuyez sur Connect.','OAuth client id'=>'Identifiant client OAuth','OAuth client secret'=>'Secret du client OAuth','Leave empty to keep the saved secret'=>'Laissez vide pour conserver le secret enregistré','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Dans la Google Cloud Console, activez l’API Google Drive API, puis créez un client OAuth de type « Web application » avec cette adresse comme URI de redirection autorisée :','Save, then press Connect. The plugin only sees the files it creates.'=>'Enregistrez, puis appuyez sur Connecter. L’extension ne voit que les fichiers qu’elle crée.','Folder inside the storage (optional)'=>'Dossier dans l’espace de stockage (facultatif)','Save storage'=>'Économiser du stockage','Import a backup from another plugin or host'=>'Importer une sauvegarde depuis une autre extension ou un autre hébergeur','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Importez un site à partir d’une sauvegarde créée par UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate ou toute archive zip/tar d’un site WordPress avec son dump .sql. Le contenu est transféré dans wp-content et la base de données remplace celle de ce site ; les adresses sont automatiquement remplacées par celles de ce site.','Upload from your computer'=>'Téléverser depuis votre ordinateur','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Choisissez tous les fichiers de la sauvegarde en même temps (UpdraftPlus en crée plusieurs). Les fichiers volumineux sont envoyés en petits morceaux, la limite de téléversement de votre hébergeur ne s’applique donc pas.','Or from links (Google Drive, Dropbox or any download address)'=>'Ou depuis des liens (Google Drive, Dropbox ou toute adresse de téléchargement)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Un lien par ligne. Pour Google Drive et Dropbox, partagez le fichier avec « tous les utilisateurs disposant du lien » et collez ce lien ; désactivez ensuite le partage.','Or a file already on this server'=>'Ou un fichier déjà présent sur ce serveur','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Téléversez les archives par FTP ou via le gestionnaire de fichiers de votre hébergeur dans %s, puis rechargez cette page.','Or a deploy code from another site'=>'Ou un code de déploiement provenant d’un autre site','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Si un autre site vous a fourni un code de déploiement Zinn® Backups, collez-le ici pour copier cette sauvegarde sur ce site sans partager ses clés de stockage. Un code fonctionne pendant quelques heures ; traitez-le comme un mot de passe.','Passphrase (only if that backup is encrypted)'=>'Phrase secrète (uniquement si cette sauvegarde est chiffrée)','Import'=>'Importer','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Je comprends que l’importation remplace le contenu et la base de données de ce site. Ensuite, connectez-vous avec un compte du site importé.','Moving to Zinn® hosting?'=>'Vous passez à l’hébergement Zinn® ?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® peut transférer votre site depuis votre ancien hébergeur pour vous. Si votre ancien hébergeur ne vous donne aucun accès FTP, SSH ou au panneau de contrôle, installez Zinn® Migrate sur l’ancien site ; cela crée une archive unique que vous pouvez importer ici ou transmettre à Zinn®.','What goes into a backup'=>'Ce que contient une sauvegarde','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Inclure les fichiers propres à WordPress (wp-admin, wp-includes). Généralement pas nécessaire : WordPress peut toujours être réinstallé.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Excluez également ces dossiers ou fichiers (un par ligne, par rapport au dossier WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Toujours exclus : caches, espace temporaire de mise à jour et propres dossiers d’archives des autres extensions de sauvegarde :','Size of each part (MB)'=>'Taille de chaque partie (Mo)','Save settings'=>'Enregistrer les réglages','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Une partie de la sauvegarde n’a pas pu être ouverte en écriture. Vérifiez que wp-content dispose d’espace libre.','A backup part could not be written. Check that wp-content has free space.'=>'Une partie de la sauvegarde n’a pas pu être écrite. Veuillez vérifier que wp-content dispose d’espace libre.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Connectez d’abord une destination de stockage dans l’onglet Storage : les sauvegardes sont conservées dans votre propre espace de stockage, pas sur ce serveur.','Multisite networks are not supported yet.'=>'Les réseaux de sites (Multisite) ne sont pas encore pris en charge.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'Le PHP de ce serveur ne dispose pas de l’extension ZipArchive. Demandez à votre hébergeur de l’activer.','Starting'=>'Démarrage en cours','Listing files'=>'Liste des fichiers en cours','Backing up the database'=>'Sauvegarde de la base de données en cours','Packing files'=>'Empaquetage des fichiers','Uploading to your storage'=>'Téléversement vers votre espace de stockage','Finishing'=>'Finalisation','The backup reached an unknown stage.'=>'La sauvegarde a atteint une étape inconnue.','Backup %s started.'=>'Sauvegarde de %s démarrée.','Found %1$s files (%2$s).'=>'%1$s fichiers trouvés (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Base de données : %1$d tables, %2$s lignes, %3$s compressées.','Backup complete: %1$s stored in %2$d destination.'=>'Sauvegarde terminée : %1$s stocké dans %2$d destination.' . "\0" . 'Sauvegarde terminée : %1$s stocké dans %2$d destinations.' . "\0" . 'Sauvegarde terminée : %1$s stocké dans %2$d destinations.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Certaines parties déjà téléversées n’ont pas pu être supprimées de votre stockage ; elles se trouvent dans un dossier de sauvegarde incomplète et ne sont jamais proposées pour la restauration.','A storage destination was removed while the backup was running.'=>'Une destination de stockage a été supprimée pendant l’exécution de la sauvegarde.','That is not a backup folder.'=>'Ce n’est pas un dossier de sauvegarde.','That storage destination is no longer saved on this site.'=>'Cette destination de stockage n’est plus enregistrée sur ce site.','Later incremental backups are built on this one. Delete those first.'=>'Les sauvegardes incrémentielles ultérieures reposent sur celle-ci. Supprimez-les d’abord.','This file is not an encrypted Zinn® Backups file.'=>'Ce fichier n’est pas un fichier Zinn® Backups chiffré.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'La sauvegarde n’a pas pu être déchiffrée : la phrase secrète est incorrecte ou le fichier est endommagé.','The encrypted backup file is incomplete.'=>'Le fichier de sauvegarde chiffré est incomplet.','The database file could not be written. Check that wp-content has free space.'=>'Le fichier de base de données n’a pas pu être écrit. Vérifiez que wp-content dispose d’espace libre.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Ce n’est pas un code de déploiement. Un code de déploiement commence par zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Ce code de déploiement est endommagé. Veuillez le copier à nouveau depuis l’autre site.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Le code de déploiement a expiré ou sa sauvegarde a été supprimée. Créez un nouveau code sur l’autre site.','That deploy code does not point at a Zinn® Backups backup.'=>'Ce code de déploiement ne pointe pas vers une sauvegarde Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Le code de déploiement a expiré. Générez un nouveau code sur l’autre site.','The server stopped honouring partial downloads. Start the import again.'=>'Le serveur ne prend plus en charge les téléchargements partiels. Veuillez recommencer l’importation.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Le lien a ouvert une page web au lieu d’un fichier. Pour Google Drive et Dropbox, partagez le fichier avec « tous les utilisateurs disposant du lien » et collez ce lien.','The link answered with HTTP %d.'=>'Le lien a répondu avec HTTP %d.','The file list could not be written.'=>'Impossible d’écrire la liste des fichiers.','The storage service could not be reached: %s'=>'Impossible de joindre le service de stockage : %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s a répondu avec HTTP %2$d : %3$s','no details given'=>'Aucun détail fourni','You are not allowed to manage backups.'=>'Vous n’êtes pas autorisé à gérer les sauvegardes.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Cochez la case pour confirmer que la restauration remplace les fichiers et la base de données de ce site.','Save the destination first.'=>'Enregistrez d’abord la destination.','Connected: a test file was written and removed.'=>'Connecté : un fichier de test a été écrit et supprimé.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Saisissez d’abord la clé d’application de votre application Dropbox (voir les étapes à côté du formulaire).','This kind of storage does not sign in.'=>'Ce type de stockage ne se connecte pas.','The sign-in expired. Press Connect again.'=>'La connexion a expiré. Veuillez appuyer de nouveau sur Connecter.','Dropbox is connected.'=>'Dropbox est connecté.','Settings saved.'=>'Réglages enregistrés.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Une autre sauvegarde, restauration ou importation est en cours. Veuillez attendre qu’elle se termine ou l’annuler.','The upload was not started properly. Start again.'=>'Le téléversement n’a pas démarré correctement. Veuillez recommencer.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Le fragment n’est pas arrivé. Votre serveur limite peut-être la taille des téléversements ; veuillez réessayer.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Cochez la case pour confirmer que l’importation remplace le contenu et la base de données de ce site.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Choisissez une archive à importer : téléversez-la, collez un lien ou choisissez-en une dans le dossier d’importation.','Hosting customer? Get %1$d%% off %2$s'=>'Client de l’hébergement ? Bénéficiez de %1$d %% de réduction sur %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'En tant que client de l’hébergement Zinn Digital®, vous bénéficiez d’un code personnel offrant %d%% de réduction sur votre premier paiement. Les renouvellements sont au tarif normal.','Get my %d%% code and go to checkout'=>'Obtenez mon code de %d%% et passez à la caisse','Sorry, you are not allowed to do that.'=>'Désolé, vous n’avez pas l’autorisation de faire cela.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Cette réduction s’adresse aux clients disposant d’un plan d’hébergement payant en règle. Les essais gratuits ne sont pas éligibles.','You have already used your hosting-customer discount for this plugin.'=>'Vous avez déjà utilisé votre remise client d’hébergement pour cette extension.','We could not get your code just now. Please try again in a few minutes.'=>'Nous n’avons pas pu récupérer votre code à l’instant. Veuillez réessayer dans quelques minutes.','Reading the backup'=>'Lecture de la sauvegarde en cours','Downloading the archive'=>'Téléchargement de l’archive en cours','Recognising the archive'=>'Reconnaissance de l’archive','Restoring files'=>'Restauration des fichiers','Downloading the database'=>'Téléchargement de la base de données','Restoring the database'=>'Restauration de la base de données','Updating the site address'=>'Mise à jour de l’adresse du site','Switching to the restored database'=>'Basculement vers la base de données restaurée','The restore reached an unknown stage.'=>'La restauration a atteint une étape inconnue.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Ce dossier ne contient aucune sauvegarde Zinn® Backups complète (le manifeste est manquant).','This backup is encrypted. Enter its passphrase to restore it.'=>'Cette sauvegarde est chiffrée. Saisissez sa phrase secrète pour la restaurer.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Cette sauvegarde incrémentielle nécessite la sauvegarde %s, qui n’est plus présente dans le stockage.','Restoring the backup of %1$s (%2$d file parts).'=>'Restauration de la sauvegarde de %1$s (%2$d parties de fichier).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Le fichier %1$s n’a pas pu être écrasé car ce site n’est pas autorisé à le modifier, et il a été laissé en l’état : %2$s' . "\0" . '%1$s fichiers n’ont pas pu être écrasés car ce site n’est pas autorisé à les modifier, et ont été laissés tels quels : %2$s' . "\0" . '%1$s fichiers n’ont pas pu être écrasés car ce site n’est pas autorisé à les modifier, et ont été laissés tels quels : %2$s','Restored %s files.'=>'%s fichiers restaurés.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s ne correspond pas à sa somme de contrôle après le téléchargement. La copie dans le stockage est peut-être endommagée.','%s did not arrive. Upload it again.'=>'%s n’est pas arrivé. Veuillez le téléverser à nouveau.','Recognised: %s.'=>'Reconnu : %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'%1$s fichiers importés dans wp-content (%2$s ignorés : caches, drop-ins et dossiers d’autres extensions de sauvegarde).','The archive has no database dump, so only files were imported.'=>'L’archive ne contient aucun dump de base de données, seuls les fichiers ont donc été importés.','Database restored into %d temporary tables.'=>'Base de données restaurée dans %d tables temporaires.','%s has no WordPress tables in it and was skipped.'=>'%s ne contient aucune table WordPress et a été ignoré.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'La base de données de la sauvegarde ne contient aucune table WordPress, rien n’a donc été remplacé.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Cette sauvegarde provient d’un réseau de sites. La restauration d’un réseau sur un site unique n’est pas prise en charge.','Moving the content from %1$s to %2$s.'=>'Déplacement du contenu de %1$s vers %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Restauration terminée. Si vous êtes déconnecté, connectez-vous avec un compte du site restauré.','Restore complete.'=>'Restauration terminée.','%1$s — trying again in %2$d seconds.'=>'%1$s — nouvelle tentative dans %2$d secondes.','Cancelled.'=>'Annulé.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Les sauvegardes vont vers une seule destination de stockage. Modifiez ou supprimez celle que vous avez pour en utiliser une autre.','The database file could not be opened.'=>'Impossible d’ouvrir le fichier de base de données.','The database refused a statement from the backup: %1$s (%2$s…)'=>'La base de données a refusé une instruction de la sauvegarde : %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Les tables restaurées n’ont pas pu être interchangées : %s. Votre site reste inchangé.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Il n’y a aucun dossier accessible en écriture pour les fichiers de sauvegarde temporaires. Rendez wp-content accessible en écriture et réessayez.','Could not create a folder for this job.'=>'Impossible de créer un dossier pour cette tâche.','%s — guides and services'=>'%s — guides et services','User guides'=>'Guides d’utilisation','Read the %s user guide'=>'Lisez le guide d’utilisation de %s','Hide this'=>'Masquer ceci','Zinn® hosting for WordPress'=>'Hébergement Zinn® pour WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, sauvegardes quotidiennes, migration gratuite et un panneau de configuration conçu pour les personnes qui gèrent plus d’un site.','The Zinn® marketplace'=>'La place de marché Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Achetez et vendez des sites établis, des domaines et des placements de liens, l’argent étant conservé en toute sécurité jusqu’à ce que les deux parties soient satisfaites.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — engagez des personnes dont c’est le métier','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Notre place de marché freelance mondiale : parcourez plus de 10 000 services prêts à l’emploi proposés par des rédacteurs, designers, développeurs et experts SEO, ou publiez un projet et laissez-les faire des offres.','See the Zinn Digital® release notes.'=>'Consultez les notes de version de Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Le service de mise à jour Zinn® n’a pas fourni de lien de téléchargement pour cette mise à jour. Vérifiez que ce site peut accéder à la plateforme Zinn®, puis réessayez.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'La mise à jour n’a pas pu être téléchargée depuis le service de mise à jour Zinn® (%s). Veuillez réessayer dans quelques minutes.','The downloaded update failed its integrity check and was not installed.'=>'La mise à jour téléchargée n’a pas passé le contrôle d’intégrité et n’a pas été installée.','The zip archive could not be opened. It may be damaged or incomplete.'=>'L’archive zip n’a pas pu être ouverte. Elle est peut-être endommagée ou incomplète.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Ce fichier .wpress utilise un format que nous ne pouvons pas lire (il est peut-être compressé ou chiffré par All-in-One WP Migration). Veuillez l’exporter à nouveau sans chiffrement.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Il s’agit d’un fichier Duplicator « DupArchive » (.daf). Dans Duplicator, générez à nouveau le paquet en définissant le format d’archive sur ZIP, puis importez-le.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Cette sauvegarde de base de données UpdraftPlus est chiffrée. Déchiffrez-la dans UpdraftPlus (ou désactivez le chiffrement de la base de données et effectuez une nouvelle sauvegarde), puis importez-la.','Database dump'=>'Dump de la base de données','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s n’est pas une archive de sauvegarde que nous pouvons lire (zip, tar, tar.gz, .wpress, .sql ou .sql.gz).','Website archive'=>'Archive du site Web','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s ne contient aucun contenu WordPress (aucun dossier wp-content et aucun export de base de données).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ce fichier .wpress est chiffré ou compressé par All-in-One WP Migration. Veuillez l’exporter à nouveau en désactivant le chiffrement et la compression, puis importez-le.','Other S3-compatible storage'=>'Autre stockage compatible S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 ou compatible S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Les clés de stockage n’ont pas pu être lues sur ce site. Saisissez à nouveau la clé secrète dans l’onglet Stockage.','This kind of storage is not known.'=>'Ce type de stockage n’est pas connu.','Choose a kind of storage.'=>'Choisissez un type de stockage.','Enter the bucket name and the access key.'=>'Saisissez le nom du compartiment et la clé d’accès.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Saisissez l’identifiant de votre compte Cloudflare (ou le point de terminaison R2 complet).','Enter the endpoint address of your storage.'=>'Saisissez l’adresse du point de terminaison de votre stockage.','Enter the OAuth client id from your Google Cloud project.'=>'Saisissez l’OAuth client id de votre projet Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox n’a pas renvoyé de jeton d’actualisation. Veuillez relancer la connexion.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox n’est pas connecté. Veuillez le reconnecter dans l’onglet Stockage.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google n’a pas renvoyé de jeton d’actualisation. Supprimez ce site de l’accès tiers de votre compte Google et reconnectez-vous.','That file is not in Google Drive any more.'=>'Ce fichier n’est plus dans Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive n’est pas connecté. Veuillez le reconnecter dans l’onglet Stockage.','The storage service did not start the upload.'=>'Le service de stockage n’a pas démarré le téléversement.','The storage service sent a reply that could not be read.'=>'Le service de stockage a envoyé une réponse illisible.','A temporary backup file could not be read.'=>'Impossible de lire un fichier de sauvegarde temporaire.','A deploy link is read-only.'=>'Un lien de déploiement est en lecture seule.','The deploy code has no link for a file this backup needs.'=>'Le code de déploiement ne contient aucun lien pour un fichier requis par cette sauvegarde.','The deploy link'=>'Le lien de déploiement']];